"use client";

import { useMemo, useState } from "react";
import { ArrowLeft, ArrowRight, CheckCircle2, RotateCcw } from "lucide-react";
import { assessmentQuestions } from "@/data/assessment";

export default function AssessmentForm() {
  const [step, setStep] = useState(0);
  const [answers, setAnswers] = useState<Record<string, number>>({});
  const finished = step >= assessmentQuestions.length;
  const score = useMemo(() => Object.values(answers).reduce((a, b) => a + b, 0), [answers]);

  if (finished) {
    const label = score >= 80 ? "Strong foundation" : score >= 55 ? "Some gaps to address" : "High-priority improvements";
    return (
      <div className="rounded-3xl border border-white/10 bg-white/[0.035] p-7 md:p-10">
        <div className="mb-8 flex items-center gap-3 text-emerald-200"><CheckCircle2 /> Assessment complete</div>
        <div className="mb-3 text-sm uppercase tracking-[0.2em] text-white/40">Technology health score</div>
        <div className="mb-4 text-6xl font-semibold tracking-tight">{score}<span className="text-2xl text-white/30"> / 100</span></div>
        <div className="mb-8 text-xl text-white/80">{label}</div>
        <div className="mb-8 h-2 overflow-hidden rounded-full bg-white/10"><div className="h-full rounded-full bg-emerald-200" style={{ width: `${score}%` }} /></div>
        <p className="mb-8 max-w-2xl leading-7 text-white/55">This demo score is based on five common controls: MFA, backup, device management, patching, and offboarding. A real assessment would also review identity, network security, licensing, documentation, and recovery testing.</p>
        <button onClick={() => { setStep(0); setAnswers({}); }} className="inline-flex items-center gap-2 rounded-full border border-white/15 px-5 py-3 text-sm hover:bg-white/5"><RotateCcw size={16} /> Start over</button>
      </div>
    );
  }

  const q = assessmentQuestions[step];
  const selected = answers[q.id];

  return (
    <div className="rounded-3xl border border-white/10 bg-white/[0.035] p-7 md:p-10">
      <div className="mb-8 flex items-center justify-between text-sm text-white/40">
        <span>Question {step + 1} of {assessmentQuestions.length}</span>
        <span>{Math.round((step / assessmentQuestions.length) * 100)}%</span>
      </div>
      <div className="mb-8 h-1 overflow-hidden rounded-full bg-white/10"><div className="h-full bg-emerald-200 transition-all" style={{ width: `${(step / assessmentQuestions.length) * 100}%` }} /></div>
      <h2 className="mb-3 max-w-2xl text-2xl font-semibold tracking-tight md:text-3xl">{q.question}</h2>
      <p className="mb-8 max-w-2xl leading-7 text-white/50">{q.detail}</p>
      <div className="grid gap-3">
        {q.options.map(option => (
          <button
            key={option.label}
            onClick={() => setAnswers({ ...answers, [q.id]: option.value })}
            className={`rounded-2xl border p-4 text-left transition ${selected === option.value ? "border-emerald-200/50 bg-emerald-200/10 text-white" : "border-white/10 bg-black/10 text-white/65 hover:border-white/20 hover:bg-white/[0.03]"}`}
          >
            {option.label}
          </button>
        ))}
      </div>
      <div className="mt-8 flex justify-between">
        <button onClick={() => setStep(Math.max(0, step - 1))} disabled={step === 0} className="inline-flex items-center gap-2 rounded-full px-4 py-2 text-sm text-white/50 disabled:opacity-20"><ArrowLeft size={16} /> Back</button>
        <button onClick={() => setStep(step + 1)} disabled={selected === undefined} className="inline-flex items-center gap-2 rounded-full bg-white px-5 py-3 text-sm font-medium text-black disabled:cursor-not-allowed disabled:opacity-30">Continue <ArrowRight size={16} /></button>
      </div>
    </div>
  );
}
